INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000003d',1,'APPROVED','PUBLISHED',
'{"objectives":["Express quantity and measurement in Kannada","Use kilo/litre/metre with Kannada numbers","Talk about weight, distance, and volume"],"explanation":{"intro":"Quantity and measurement vocabulary covers how to express amounts, weights, distances, and volumes in Kannada — essential for shopping, cooking, and daily life.","culturalNote":"Measurement in Karnataka: the metric system is official and used everywhere. However, traditional measures are still used informally: one seer (approximately 933g — older unit), one tola (older gold/spice weight). In markets: vegetables are sold by kilo (kilo), rice by kilo or bag (bag), dal (lentils) by kilo, oil by litre (litre). Petrol: always in litres — petrol prices vary daily and are a frequent topic of discussion. Land measurement: guntha (1/40 of an acre), acre (ek acre), ground (traditional South Indian area unit ≈ 2400 sq ft — used in real estate). Milk (haalu): sold by litre in Nandini pouches (Nandini = Karnataka''s government milk brand — very trusted). Cloth: measured in metres. Gold: grams (gram). Distance: kilometres (KM). Road signs: km markers common on national highways. Petrol station distance: X km aaguttade (it is X km — X km away)."},"examples":[{"sentence":"Naakke renDu kilo tomato haagu ondu kilo eeruLLi beku.","english":"I need two kilos of tomato and one kilo of onion."},{"sentence":"Bengaluru inda Mysuru ge saathu nooraippattu KM ide.","english":"It is about 170 KM from Bengaluru to Mysuru."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can express quantity and measurement in everyday Kannada situations."}}',
'{"items":[{"word":"kilo","translation":"kilogram","transliteration":"kilo","pronunciation":"KI-lo","example":"ondu kilo"},{"word":"litre","translation":"litre","transliteration":"litre","pronunciation":"LI-tar","example":"ondu litre"},{"word":"metre","translation":"metre","transliteration":"metre","pronunciation":"MEE-tar","example":"ondu metre"},{"word":"gram","translation":"gram","transliteration":"gram","pronunciation":"gram","example":"oompattu gram"},{"word":"saathu","translation":"approximately/about","transliteration":"saathu","pronunciation":"SAA-thu","example":"saathu nooru rupai"},{"word":"hEchhu","translation":"more (quantity)","transliteration":"hEchhu","pronunciation":"HEE-chhu","example":"hEchhu beku"}]}',
'{"title":"X kilo/litre/metre — quantity expressions in Kannada","pattern":"Ondu kilo X = one kilo of X. Eradu litre X = two litres of X. Saathu X = approximately X. HEcchina = more/excess (adjective). Kammina = less/fewer. Yaavadu X beku? = which one do you need? Eshtu beku? = how much/many do you need? Eshtu aagutte? = how much will it cost?","explanation":"Quantity in Kannada: Kannada numbers + measurement units. One: ondu, two: eradu, three: mooru, four: naalku, five: aidu, six: aaru, seven: yelu, eight: yenTu, nine: ombattu, ten: hattu. Fractions: ondara (one and a half — ondu+ara = one+half), eradara (two and a half), kaal (quarter — kaal kilo = 250g). Half kilo: aradhu kilo (half = aradhu). Quarter kilo: kaal kilo (kaal = quarter). Double: eradu paTTu (twice the amount — paTTu = times). Approximation: saathu (about/around), aadashTu (nearly). Big amount: thumba jaasthi (very much), chinna jaasthi (a lot more).","examples":[{"sentence":"Naakke aradhu kilo neyyi haagu kaal litre haalu beku.","english":"I need half a kilo of ghee and a quarter litre of milk."},{"sentence":"Ee maney saathu mooru nooraippattu square feet aagutte.","english":"This house is approximately 350 square feet."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"saathu means?","options":["approximately/about","exactly","more","less"],"correctAnswer":"approximately/about"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I need two kilos of tomato and one kilo of onion.","options":["Naakke renDu kilo tomato haagu ondu kilo eeruLLi beku.","Naakke mooru kilo tomato haagu ondu kilo eeruLLi beku.","Naakke renDu kilo tomato aadare ondu kilo eeruLLi beku.","Naakke renDu kilo tomato haagu eradu kilo eeruLLi beku."],"correctAnswer":"Naakke renDu kilo tomato haagu ondu kilo eeruLLi beku."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Bengaluru inda Mysuru ge ___ nooraippattu KM ide.","options":["saathu","kammina","hEchhu","eshtu"],"correctAnswer":"saathu"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I need half a kilo of ghee and a quarter litre of milk.","wordBankItems":["Naakke","aradhu","kilo","neyyi","haagu","kaal","litre","haalu","beku","."],"correctAnswer":"Naakke aradhu kilo neyyi haagu kaal litre haalu beku ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"hEchhu means?","options":["more (quantity)","less","enough","exact"],"correctAnswer":"more (quantity)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000003e',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe nature and the natural environment in Kannada","Talk about trees, rivers, and landscapes","Use Kannada vocabulary for environmental topics"],"explanation":{"intro":"Nature and environment vocabulary covers how to describe natural landscapes, flora, fauna, weather phenomena, and environmental topics in Kannada.","culturalNote":"Nature in Karnataka: Karnataka is one of India''s most biodiverse states. Western Ghats (Sahyadri — UNESCO World Heritage Site) — one of the world''s eight biodiversity hotspots. National parks: Bandipur National Park (Project Tiger — southern Karnataka), Nagarhole National Park (Rajiv Gandhi — part of Nilgiri Biosphere Reserve), Bhadra Tiger Reserve, Anshi-Dandeli Tiger Reserve (Kali Tiger Reserve). Trees: sandalwood tree (chandana mara — Karnataka''s state tree), silver oak, eucalyptus (neelagiri), teakwood (teku). Flowers: Jasmine (mallige — Mysuru is famous for its mallige flowers). Insects: silk moth (haalu huli — Mysuru and Kolar are silk producing). Rivers: Kaveri, Tungabhadra, Sharavathi (Jog Falls). Jog Falls: India''s second-highest waterfall (253m). Western Ghats rainfall: receives very high rainfall during monsoon — critical source of drinking water for peninsular India."},"examples":[{"sentence":"Western Ghats alli thumba channa vanavya ide, anek pakshi nodi bode.","english":"The Western Ghats has very beautiful wildlife, I was lucky to see many birds."},{"sentence":"Kaveri naadi beLevu naade, ee naadiya neeru naakke ishtavagutte.","english":"The Kaveri river is the lifeblood of this state, I love the water of this river."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe nature, landscapes, and the environment in Kannada."}}',
'{"items":[{"word":"mara","translation":"tree","transliteration":"mara","pronunciation":"MA-ra","example":"dodda mara"},{"word":"naadi","translation":"river","transliteration":"naadi","pronunciation":"NAA-di","example":"naadi beLevu"},{"word":"kaadu","translation":"forest","transliteration":"kaadu","pronunciation":"KAA-du","example":"dense kaadu"},{"word":"pakshi","translation":"bird","transliteration":"pakshi","pronunciation":"PAK-shi","example":"pakshi nodide"},{"word":"vanavya","translation":"wildlife/wild animals","transliteration":"vanavya","pronunciation":"va-NAV-ya","example":"vanavya kaanisuttade"},{"word":"naadi beLevu","translation":"lifeblood (lit. river of growth/life)","transliteration":"naadi beLevu","pronunciation":"NAA-di be-LE-vu","example":"beLevu naade"}]}',
'{"title":"Western Ghats alli vanavya — nature vocabulary in Kannada","pattern":"X alli Y ide = there is Y in X. X kaandide = I saw X (kaandide = I saw — alternative to nodide for wildlife/sighting). Vanavya (wildlife), pakshi (bird), mara (tree), naadi (river), betta (hill), kere (lake), mallige (jasmine). Describing nature: thumba channa (very beautiful), hasi bana (green color), suvaasane (fragrance — su+vaasane = good smell).","explanation":"Nature vocabulary in Kannada: mara (tree), hoo (flower), hannu (fruit), aaku (leaf — aaku = leaf in Kannada, remember: aaku for leaf, haakuttaare for wearing). Water bodies: naadi (river), kere (lake/tank), samudra (sea/ocean — samudra = ocean), haLa (stream/small river). Terrain: betta (hill), parvata (mountain), kaadu (forest), godde (mound/small hill). Animals: huli (tiger), aane (elephant), siMha (lion), kari (black — note: kari aane = black elephant often used metaphorically). Environmental issue: pollution (maalinye), climate change (havamaan badalavaaNi). Conservation: samrakshaNe (conservation). Kannadigas are proud of their state''s biodiversity.","examples":[{"sentence":"Bandipur kaadu alli naanu ondu huli nodi bode, thumba bhaya aayitu aadare channa anubhava.","english":"In the Bandipur forest I was lucky to see a tiger, I was very scared but it was a beautiful experience."},{"sentence":"Jog falls noduvudu oru sweeping experience, neeru thumba jhurHhur jaaLuvaaglide.","english":"Seeing Jog Falls is an overwhelming experience, the water flows so powerfully."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"pakshi means?","options":["bird","animal","tree","forest"],"correctAnswer":"bird"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The Western Ghats has very beautiful wildlife, I was lucky to see many birds.","options":["Western Ghats alli thumba channa vanavya ide, anek pakshi nodi bode.","Western Ghats alli thakku channa vanavya ide, anek pakshi nodi bode.","Bandipur alli thumba channa vanavya ide, anek pakshi nodi bode.","Western Ghats alli thumba channa vanavya ide, ondu pakshi nodi bode."],"correctAnswer":"Western Ghats alli thumba channa vanavya ide, anek pakshi nodi bode."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Bandipur kaadu alli naanu ondu huli nodi bode, thumba ___ aayitu.","options":["bhaya","channa","santosha","takasele"],"correctAnswer":"bhaya"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The Kaveri river is the lifeblood of this state.","wordBankItems":["Kaveri","naadi","beLevu","naade",",","ee","naadiya","neeru","naakke","ishtavagutte","."],"correctAnswer":"Kaveri naadi beLevu naade , ee naadiya neeru naakke ishtavagutte ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"vanavya means?","options":["wildlife/wild animals","nature","forest","bird"],"correctAnswer":"wildlife/wild animals"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000003f',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss education and studies in Kannada","Use naanu X oduttiddeeni for talking about studying","Name schools, colleges, and subjects in Kannada"],"explanation":{"intro":"Education vocabulary covers how to talk about school, college, subjects, degrees, and education in Kannada.","culturalNote":"Education in Karnataka: Karnataka has a strong education system. IIT Bengaluru (Indian Institute of Technology Dhaarwad), IISc Bengaluru (Indian Institute of Science — one of the world''s top research institutions), NIMHANS (National Institute of Mental Health and Neuro Sciences). CMR Group, Christ University, Manipal Group, PES University (prominent private universities in Bengaluru). Government universities: Bengaluru University, Mysuru University (with India''s largest campus), Dharwad University of Agricultural Sciences, Gulbarga University. Medium of instruction: Kannada-medium schools (government schools) vs English-medium schools (private CBSE/ICSE/IB). Competitive exams: CET (Karnataka Common Entrance Test — for engineering), NEET (medical), JEE (IITs), UPSC (IAS), KPSC (Karnataka Public Service Commission). Textbooks: Karnataka state board textbooks are available in Kannada and English. Scholarships: SC/ST scholarships, post-matric scholarships."},"examples":[{"sentence":"Naanu abhi Bengaluru University alli MA Kannada odi kaliyuttiddeeni.","english":"I am currently studying/learning MA Kannada at Bengaluru University."},{"sentence":"Nanna geleya IIT Dhaarwad alli engineering maaduttidaane.","english":"My friend is doing engineering at IIT Dharwad."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can discuss education, studies, and academic subjects in Kannada."}}',
'{"items":[{"word":"shaale","translation":"school","transliteration":"shaale","pronunciation":"SHAA-le","example":"shaale ge hoguttini"},{"word":"college","translation":"college/university","transliteration":"college","pronunciation":"KOL-ej","example":"college alli oduttiddeeni"},{"word":"vishaya","translation":"subject (academic)","transliteration":"vishaya","pronunciation":"VI-sha-ya","example":"iShTa vishaya"},{"word":"pariksha","translation":"exam/test","transliteration":"pariksha","pronunciation":"pa-RIK-sha","example":"pariksha bagge"},{"word":"odi kaliyuttiddeeni","translation":"am studying/learning (present continuous — studying right now over a period)","transliteration":"odi kaliyuttiddeeni","pronunciation":"o-di ka-li-YUT-teed-dee-ni","example":"engineering odi kaliyuttiddeeni"},{"word":"degree","translation":"degree (academic)","transliteration":"degree","pronunciation":"di-GRI","example":"degree aayitu"}]}',
'{"title":"Naanu X college alli Y oduttiddeeni — I am studying Y at X college","pattern":"Naanu X alli Y oduttiddeeni = I am studying Y at X (continuous — over a period). Oduttiddeeni = I am studying/reading (progressive). Degree: naanu X degree maaduttiddeeni (I am doing an X degree). Passed: degree aayitu (degree completed). Stream: science/commerce/arts stream (English words used). Year: first/second/third/final year. Preparing: pariksha preparation maaduttiddeeni (I am preparing for the exam).","explanation":"Education vocabulary in Kannada: (1) School levels: primary shaale (primary school), high shaale (high school/secondary), PU college (pre-university — after 10th grade, 2 years). (2) Higher: degree college (undergraduate), post-graduate (PG), PhD (PhD maaduttiddeeni = I am doing a PhD). (3) Subjects: maths (maths/ganita), science (vigyana), Kannada (Kannada), English (English), history (itihasa), geography (bhugola). (4) Exams: pariksha (exam), result (result), marks (marks), pass (pass), fail (fail). (5) Teaching: teacher (shaale alli) avaru thumba channa padisuttaare (they teach very well — padisuttaare = they teach). Studying hard: thumba joraagi oduttiddeeni (I am studying very hard — joraagi = with force/hard).","examples":[{"sentence":"Naanu final year engineering oduttiddeeni, naale pariksha ide.","english":"I am studying final year engineering, tomorrow there is an exam."},{"sentence":"Nanna akka UPSC preparation maaduttidaaLe, thumba jostige oduttidaaLe.","english":"My sister is preparing for UPSC, she is studying with great dedication."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"pariksha means?","options":["exam/test","subject","degree","college"],"correctAnswer":"exam/test"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I am currently studying/learning MA Kannada at Bengaluru University.","options":["Naanu abhi Bengaluru University alli MA Kannada odi kaliyuttiddeeni.","Naanu abhi Mysuru University alli MA Kannada odi kaliyuttiddeeni.","Naanu abhi Bengaluru University alli BA Kannada odi kaliyuttiddeeni.","Avanu abhi Bengaluru University alli MA Kannada odi kaliyuttidaane."],"correctAnswer":"Naanu abhi Bengaluru University alli MA Kannada odi kaliyuttiddeeni."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Naanu final year engineering oduttiddeeni, naale ___ ide.","options":["pariksha","degree","college","vishaya"],"correctAnswer":"pariksha"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: My friend is doing engineering at IIT Dharwad.","wordBankItems":["Nanna","geleya","IIT","Dhaarwad","alli","engineering","maaduttidaane","."],"correctAnswer":"Nanna geleya IIT Dhaarwad alli engineering maaduttidaane ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"odi kaliyuttiddeeni means?","options":["am studying/learning (continuous)","I studied","I will study","I was studying"],"correctAnswer":"am studying/learning (continuous)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000040',1,'APPROVED','PUBLISHED',
'{"objectives":["Ask for and give advice in Kannada","Use X maadabeku anta nambuttini for recommendations","Express what someone should or should not do"],"explanation":{"intro":"Asking for and giving advice covers how to seek guidance, make recommendations, and express what someone should or should not do in Kannada.","culturalNote":"Advice-giving culture in Karnataka: elder advice is highly valued in Karnataka culture — elders (hiriyanavaru) are considered fonts of wisdom. Common advice situations: career guidance, health advice (neighbor/family doctor), marriage advice (well-meaning relatives!). Proverbs (gaadegaLu): Kannada has a rich tradition of proverbs used in giving advice. Examples: ''Hudu hotteyali huttide'' (born from a caterpillar''s belly — meaning: greatness comes from humble origins — encouraging proverb). ''Kaiya koLLalu hiDi'' (take the hand that comes to you — meaning: accept help when offered). Advice from elders: typically given firmly and directly in Karnataka — seen as care, not as intrusion. Doctor''s advice: doctor heLida maaTu keLebeeku (one must listen to what the doctor says — important for health outcomes). Modern advice: professional advice (Chartered Accountant, lawyer) — often sought within the community network."},"examples":[{"sentence":"Naakke yochane kodi, ee college alli sereyu beku aa beda aa?","english":"Give me your thoughts, should I join this college or not?"},{"sentence":"Naanu nimage heLuttini — pratidinaa vyayaama maadabeku, shareeraake channa agutte.","english":"I will tell you — you should exercise every day, it is good for the body."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can ask for advice and give recommendations in Kannada."}}',
'{"items":[{"word":"yochane kodi","translation":"give your thoughts/advice (request)","transliteration":"yochane kodi","pronunciation":"YO-cha-ne KO-di","example":"yochane kodi dayavittu"},{"word":"salahe","translation":"advice/counsel","transliteration":"salahe","pronunciation":"SA-la-he","example":"channa salahe kodi"},{"word":"maadabeku","translation":"should do/must do","transliteration":"maadabeku","pronunciation":"MAA-da-be-ku","example":"vyayaama maadabeku"},{"word":"maadabaaradu","translation":"should not do/must not do","transliteration":"maadabaaradu","pronunciation":"MAA-da-baa-ra-du","example":"maadabaaradu"},{"word":"vyayaama","translation":"exercise/physical activity","transliteration":"vyayaama","pronunciation":"vya-YAA-ma","example":"vyayaama maadabeku"},{"word":"heLuttini","translation":"I will tell/say (future of heLu)","transliteration":"heLuttini","pronunciation":"he-LUT-ti-ni","example":"naanu heLuttini"}]}',
'{"title":"X maadabeku / X maadabaaradu — should do / should not do (advice in Kannada)","pattern":"X maadabeku = one should do X / you should do X (general recommendation). X maadabaaradu = one should not do X (prohibition/recommendation against). Nimage heLuttini = I will tell you (giving advice). Asking for advice: naakke salahe kodi (give me advice). Taking advice: ee salahe heLiddaakke dhanyavadagalu (thank you for giving this advice).","explanation":"Advice vocabulary in Kannada: maadabeku (should do), maadabaaradu (should not do). Both are impersonal — they apply to anyone/everyone. To say YOU should do: neevu X maadabeku (formal) / neenu X maadabeku (informal). Health advice: X tinnabeku (you should eat X), Y beda (don''t need Y), vishranti beku (need rest). Career advice: X field alli try maadabeku (you should try in the X field). Study advice: nityavoo odabeku (you should read every day — nityavoo = every day). General life advice: thumba koDi kaliyabeku aadare thumba hana indirabeku (you should learn a lot but also need a lot of money — common dilemma expressed as advice).","examples":[{"sentence":"Doctor heLidaare — fast food thumba tinnabaaradu, hasi tarkari hecchaagi tinnabeku.","english":"The doctor said — you should not eat a lot of fast food, you should eat more fresh vegetables."},{"sentence":"Nimage nanna salahe — English pratibha valisi, IT alli channa career agutte.","english":"My advice to you — develop your English skills, there will be a good career in IT."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"maadabaaradu means?","options":["should not do/must not do","should do","can do","will do"],"correctAnswer":"should not do/must not do"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I will tell you — you should exercise every day, it is good for the body.","options":["Naanu nimage heLuttini — pratidinaa vyayaama maadabeku, shareeraake channa agutte.","Naanu nimige heLuttini — pratidinaa vyayaama maadabeku, shareeraake channa agutte.","Naanu nimage heLide — pratidinaa vyayaama maadabeku, shareeraake channa agutte.","Naanu nimage heLuttini — pratidinaa vyayaama maadabeku, manassinaake channa agutte."],"correctAnswer":"Naanu nimage heLuttini — pratidinaa vyayaama maadabeku, shareeraake channa agutte."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Doctor heLidaare — fast food thumba tinnabaaradu, hasi tarkari hecchaagi ___ .","options":["tinnabeku","tinnabaaradu","tinnabahudu","tinnabode"],"correctAnswer":"tinnabeku"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Give me your thoughts, should I join this college or not?","wordBankItems":["Naakke","yochane","kodi",",","ee","college","alli","sereyu","beku","aa","beda","aa","?"],"correctAnswer":"Naakke yochane kodi , ee college alli sereyu beku aa beda aa ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"salahe means?","options":["advice/counsel","thought","opinion","suggestion"],"correctAnswer":"advice/counsel"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000041',1,'APPROVED','PUBLISHED',
'{"objectives":["Express nuanced emotions in Kannada","Use naakke X bhava aagutte for emotional states","Describe happiness, sadness, anxiety, and excitement"],"explanation":{"intro":"Emotions and inner feelings covers a rich vocabulary for expressing how you feel internally — beyond just happy or sad — including surprise, anxiety, excitement, and nostalgia.","culturalNote":"Emotions in Kannada culture: Kannadigas express emotion richly — especially through music (Carnatic and film songs), poetry (Kannada has rich literary tradition), and storytelling. Suppressed vs open expression: traditionally, men are expected to be restrained in emotional expression (especially sadness), while women are more openly expressive. Modern Bengaluru: younger generations are more open about mental health and emotional expression. The Kannada word ''hosatana'' (newness/freshness) expresses the emotion of experiencing something for the first time — a uniquely beautiful word. ''Marukaluhattu'' (forgetting and remembering — nostalgia). ''Haayenisutthade'' (it feels relieved/happy — a specific feeling of relief and pleasure combined). Kannada language has many untranslatable emotion words: ''Honnina naaLu'' (golden days — good old times — nostalgia mixed with warmth). Unique Kannada emotional words worth knowing at A2 level."},"examples":[{"sentence":"Naakke thumba santosha aagutte, nanna result channa itu.","english":"I am very happy, my result was good."},{"sentence":"Naakke chintana aagutte, naale pariksha ide haagu naanu sari odi illa.","english":"I am anxious, there is an exam tomorrow and I haven''t studied properly."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can express a range of emotions and inner feelings in Kannada."}}',
'{"items":[{"word":"santosha","translation":"happiness/joy","transliteration":"santosha","pronunciation":"san-TO-sha","example":"santosha aagutte"},{"word":"dukha","translation":"sadness/sorrow","transliteration":"dukha","pronunciation":"DUK-ha","example":"dukha aagutte"},{"word":"chintana","translation":"anxiety/worry","transliteration":"chintana","pronunciation":"chin-TA-na","example":"chintana aagutte"},{"word":"aashcharya","translation":"surprise/astonishment","transliteration":"aashcharya","pronunciation":"aash-CHAR-ya","example":"thumba aashcharya"},{"word":"bhava","translation":"feeling/emotion/sense","transliteration":"bhava","pronunciation":"BHA-va","example":"channa bhava"},{"word":"haayenisutthade","translation":"feels relieved/pleasant — a feeling of ease","transliteration":"haayenisutthade","pronunciation":"haa-ye-ni-SUT-tha-de","example":"naakke haayenisutthade"}]}',
'{"title":"Naakke X bhava aagutte — I feel X (emotion description in Kannada)","pattern":"Naakke X aagutte = I feel X (emotion). Naakke santosha aagutte (I feel happy), naakke dukha aagutte (I feel sad), naakke chintana aagutte (I feel anxious). X bhava = the feeling of X (bhava = emotion/feeling). Haayenisutthade = feels relieved/pleasant. Past emotion: naakke thumba aashcharya aayitu (I was very surprised — aayitu = it happened to me).","explanation":"Emotion vocabulary in Kannada: positive: santosha (happiness), ananada (joy — ananada/ananda), ullasa (excitement/elation), haayenisutthade (relief/pleasant ease), preethi (love/affection). Negative: dukha (sadness), chintana (anxiety/worry), bhaya (fear), koopa (anger — less common: kopa). Neutral/descriptive: aashcharya (surprise), aascharyavaagutte (it is surprising), baDale (boredom — baDale aagutte = I feel bored). Expression: naakke X aagutte (using dative naakke = to me, X happens). Causing emotion: ee sangati naakke thumba santosha koduttide (this thing/news gives me a lot of happiness).","examples":[{"sentence":"Nanna geleya bande anta heLidaaga naakke thumba santosha aayitu.","english":"When they said my friend had come, I felt very happy."},{"sentence":"Pariksha mugithu, naakke haayenisutthade — thumba joraagi odide.","english":"The exam is over, I feel relieved — I studied very hard."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"chintana means?","options":["anxiety/worry","happiness","surprise","sadness"],"correctAnswer":"anxiety/worry"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I am very happy, my result was good.","options":["Naakke thumba santosha aagutte, nanna result channa itu.","Naakke thakku santosha aagutte, nanna result channa itu.","Naakke thumba santosha aagutte, nimma result channa itu.","Naakke thumba aananada aagutte, nanna result channa itu."],"correctAnswer":"Naakke thumba santosha aagutte, nanna result channa itu."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Pariksha mugithu, naakke ___ — thumba joraagi odide.","options":["haayenisutthade","chintana aagutte","dukha aagutte","bhaya aagutte"],"correctAnswer":"haayenisutthade"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I am anxious, there is an exam tomorrow and I haven''t studied properly.","wordBankItems":["Naakke","chintana","aagutte",",","naale","pariksha","ide","haagu","naanu","sari","odi","illa","."],"correctAnswer":"Naakke chintana aagutte , naale pariksha ide haagu naanu sari odi illa ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"haayenisutthade means?","options":["feels relieved/pleasant","feels happy","feels excited","feels proud"],"correctAnswer":"feels relieved/pleasant"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000042',1,'APPROVED','PUBLISHED',
'{"objectives":["Use connectors and discourse markers to build longer sentences in Kannada","Connect ideas with haagu, aadare, yaakenendare, aaddarinda","Make conversations more fluent and natural"],"explanation":{"intro":"Useful connectors and discourse markers covers the words and phrases that link sentences together, making speech more natural and fluent in Kannada.","culturalNote":"Discourse markers in Kannada conversation: connectors in Kannada are partly borrowed from Sanskrit (haagu = and — Sanskrit-derived), partly Dravidian (aadaruvu = but even so), and partly Urdu/Persian (via North Karnataka contact). Code-switching: in urban Bengaluru, English connectors are freely mixed — ''so'', ''but'', ''because'', ''actually'', ''basically'' are very common in colloquial speech. Register awareness: in formal Kannada (news, official speeches), pure Kannada connectors are preferred; in casual conversation, mixing is natural and accepted. Literary connectors: Kannada literature uses connectors that are not found in spoken Kannada — good to know passively. Oral tradition: Yakshagana performers use elaborate connectors in their improvised speech — a mark of a skilled performer."},"examples":[{"sentence":"Naanu hogabeku itu, aadare maLe bardarbeekaagi hogalaarenu.","english":"I wanted to go, but because of the rain I could not go."},{"sentence":"Naanu Kannada kalivuttiddeeni yaakenendare Karnataka ge hogabeku ide.","english":"I am learning Kannada because I need to go to Karnataka."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can use connectors and discourse markers to build fluent, natural sentences in Kannada."}}',
'{"items":[{"word":"haagu","translation":"and/also/moreover","transliteration":"haagu","pronunciation":"HAA-gu","example":"X haagu Y"},{"word":"aadare","translation":"but/however","transliteration":"aadare","pronunciation":"AA-da-re","example":"aadare hogalaarenu"},{"word":"yaakenendare","translation":"because/the reason is","transliteration":"yaakenendare","pronunciation":"yaa-ke-NEN-da-re","example":"yaakenendare..."},{"word":"aaddarinda","translation":"therefore/because of that","transliteration":"aaddarinda","pronunciation":"aad-DA-rin-da","example":"aaddarinda hogalaarenu"},{"word":"aagalaadare","translation":"so that/in order to","transliteration":"aagalaadare","pronunciation":"aa-ga-LAA-da-re","example":"X aagalaadare Y maadu"},{"word":"aadaruvu","translation":"even so/nevertheless","transliteration":"aadaruvu","pronunciation":"aa-DA-ru-vu","example":"aadaruvu hoguttini"}]}',
'{"title":"Haagu, aadare, yaakenendare — key connectors in Kannada","pattern":"X haagu Y = X and Y. X aadare Y = X but Y. Yaakenendare Y = because Y. X aaddarinda Y = because of X, Y (therefore). X aagalaadare Y maadu = do Y so that X happens (purpose). Aadaruvu = even so/nevertheless (concession). Order: statement + connector + result/reason.","explanation":"Connectors in Kannada: (1) Addition: haagu (and/also), nantara (then/after), ee hattira (in addition to this). (2) Contrast: aadare (but), aadaruvu (even so), naanu gothillaa (I don''t know). (3) Reason: yaakenendare (because — explains why), aaddarinda (therefore — gives result). (4) Purpose: aagalaadare (in order to/so that — from aagu+laadare = for it to happen). (5) Condition: aagoothaadare (if that happens — aagu+oothaadare = if it becomes), X aadare Y (if X then Y — same aadare has double duty). (6) Discourse fillers (native Bengaluru speak): ''actually'' (actually/honestly), ''basically'' (basically), ''I mean'' (expressing), ''anyway'' (aadaruvu). Common in Bengaluru Kannada.","examples":[{"sentence":"Naanu early bandini yaakenendare traffic thumba itu, aadare meeting miss aayitu.","english":"I came early because the traffic was heavy, but the meeting was missed."},{"sentence":"Ee vishaya kalibeku aagalaadare pratidinaa practise maadabeku.","english":"In order to learn this subject, one must practice every day."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"yaakenendare means?","options":["because/the reason is","but/however","and/also","therefore"],"correctAnswer":"because/the reason is"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I wanted to go, but because of the rain I could not go.","options":["Naanu hogabeku itu, aadare maLe bardarbeekaagi hogalaarenu.","Naanu hogabeku itu, yaakenendare maLe bardarbeekaagi hogalaarenu.","Naanu hogabeku itu, aadare maLe bardarbeekaagi hoguttilla.","Avanu hogabeku itu, aadare maLe bardarbeekaagi hogalaarenu."],"correctAnswer":"Naanu hogabeku itu, aadare maLe bardarbeekaagi hogalaarenu."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Naanu Kannada kalivuttiddeeni ___ Karnataka ge hogabeku ide.","options":["yaakenendare","aadare","haagu","aaddarinda"],"correctAnswer":"yaakenendare"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: In order to learn this subject, one must practice every day.","wordBankItems":["Ee","vishaya","kalibeku","aagalaadare","pratidinaa","practise","maadabeku","."],"correctAnswer":"Ee vishaya kalibeku aagalaadare pratidinaa practise maadabeku ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"aadaruvu means?","options":["even so/nevertheless","so/therefore","and/also","in order to"],"correctAnswer":"even so/nevertheless"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000043',1,'APPROVED','PUBLISHED',
'{"objectives":["Learn the deep vocabulary of Karnataka cuisine","Describe traditional dishes with their ingredients","Talk about cooking methods and flavors"],"explanation":{"intro":"Karnataka cuisine deep dive covers the vocabulary for traditional Karnataka dishes, cooking terms, ingredients, and flavor profiles.","culturalNote":"Karnataka cuisine is diverse and region-specific: (1) Coastal Karnataka (Karavali): fish curry (meen saaru — in Tulu language), Kori Rotti (chicken curry with crispy rice wafers — Mangaluru specialty), Kotte Kadubu (steamed rice dumplings cooked in jackfruit leaves). (2) North Karnataka: Jolada Rotti (jowar flatbread — staple), Badanekai Yennegai (stuffed brinjal with spices), Hurigaalu (spiced gram mix — snack). (3) South Karnataka/Mysuru region: Mysuru Pak (famous sweet — gram flour + ghee + sugar), Obbattu/Holige (sweet stuffed flatbread), Bisi Bele Bath (rice-lentil-vegetable one-pot — literally ''hot lentil bath'' — Karnataka''s comfort food), Saaru (Karnataka rasam — thin tamarind-pepper soup). (4) Bengaluru specialty: Masala Dosa (crispy fermented crepe with potato filling), Uddina Vada (deep fried lentil donut), Chitranna (lemon rice), Kesari bath (sweet semolina pudding) — many shops serve both sweet and savory breakfast (halwa-puri style). Nandini dairy: Karnataka''s government dairy — ghee, butter, milk."},"examples":[{"sentence":"Bisi bele bath ee Karnataka preparade thumba prasidha tindi — naaLe taarhu adu tinuttini.","english":"Bisi bele bath is a very famous dish of Karnataka — I eat it almost daily."},{"sentence":"Mysuru pak thumba sihi haagu neyyi hovuvu, ee sweet naakke thumba ishtavagutte.","english":"Mysuru pak is very sweet and smells of ghee, I really like this sweet."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe Karnataka''s traditional cuisine and discuss food in depth in Kannada."}}',
'{"items":[{"word":"saaru","translation":"thin spicy broth/rasam (Karnataka-style)","transliteration":"saaru","pronunciation":"SAA-ru","example":"channa saaru"},{"word":"palya","translation":"dry vegetable side dish (stir-fried)","transliteration":"palya","pronunciation":"PAL-ya","example":"avare palya"},{"word":"kaara","translation":"spicy/hot (taste)","transliteration":"kaara","pronunciation":"KAA-ra","example":"thumba kaara"},{"word":"sihi","translation":"sweet (taste)","transliteration":"sihi","pronunciation":"SI-hi","example":"sihi tindi"},{"word":"huli","translation":"sour curry/sambar (tamarind-based)","transliteration":"huli","pronunciation":"HU-li","example":"huli tinde"},{"word":"obbattu","translation":"holige/sweet stuffed flatbread (festival sweet)","transliteration":"obbattu","pronunciation":"ob-BAT-tu","example":"obbattu maadide"}]}',
'{"title":"Karnataka cuisine vocabulary — saaru, palya, huli, obbattu","pattern":"X saaru = X''s thin broth/rasam. X palya = dry stir-fry of X. X huli = tamarind-based curry of X. Describing taste: kaara (spicy), sihi (sweet), huLi (sour — note: same word as curry!), uppu (salty). Ordering: ee X kodi (give me this X). Cooking method: beDisu (fry/cook), uLisu (steam), kuiyu (heat/warm).","explanation":"Karnataka cuisine cooking vocabulary: beDisu (to fry/cook), uLisu (to steam), koovisu (to fry deep), kaDiyu (to stir/mix), aTtu (to roast on griddle — aTTu = roti made by this method). Taste profile: kaara (spicy/hot), sihi (sweet), huLi saaru/huli (sour — also means curry using tamarind), uppu (salty), khara (pungent/sharp). Ingredients: akki (rice), bele (lentil/dal), tarkari (vegetables), meenu (fish), mamsya (meat). Traditional breakfast: idli-vaDe-saaru (idli with vaDa and saaru). Second breakfast custom: Kannadigas often have two breakfasts — tiffin first, then a heavier one! Thali (plate meal): Karnataka thali includes rice, saaru, palya, huli, papad, pickle (uppinakayi).","examples":[{"sentence":"Karnataka thali alli saaru, palya, huli, akki haagu papad seruttaare.","english":"In a Karnataka thali they serve saaru, palya, huli, rice and papad."},{"sentence":"Naakke kaara tindi thumba ishtavagutte, Bengaluru masala dosa best.","english":"I really like spicy food, Bengaluru masala dosa is the best."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"palya means?","options":["dry vegetable side dish (stir-fried)","thin broth","sweet dish","lentil curry"],"correctAnswer":"dry vegetable side dish (stir-fried)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Mysuru pak is very sweet and smells of ghee, I really like this sweet.","options":["Mysuru pak thumba sihi haagu neyyi hovuvu, ee sweet naakke thumba ishtavagutte.","Mysuru pak thumba kaara haagu neyyi hovuvu, ee sweet naakke thumba ishtavagutte.","Mysuru pak thumba sihi haagu neyyi hovuvu, ee sweet nimage thumba ishtavagutte.","Mysuru pak thakku sihi haagu neyyi hovuvu, ee sweet naakke thumba ishtavagutte."],"correctAnswer":"Mysuru pak thumba sihi haagu neyyi hovuvu, ee sweet naakke thumba ishtavagutte."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Karnataka thali alli saaru, palya, ___ , akki haagu papad seruttaare.","options":["huli","sihi","kaara","obbattu"],"correctAnswer":"huli"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: In a Karnataka thali they serve saaru, palya, huli, rice and papad.","wordBankItems":["Karnataka","thali","alli","saaru",",","palya",",","huli",",","akki","haagu","papad","seruttaare","."],"correctAnswer":"Karnataka thali alli saaru , palya , huli , akki haagu papad seruttaare ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"kaara means?","options":["spicy/hot (taste)","sweet","sour","salty"],"correctAnswer":"spicy/hot (taste)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000044',1,'APPROVED','PUBLISHED',
'{"objectives":["Give detailed directions in a city context in Kannada","Use left, right, straight, and landmark-based directions","Navigate Bengaluru and other Karnataka cities"],"explanation":{"intro":"Giving directions in a city covers how to provide and follow navigation instructions using streets, landmarks, turns, and distances in Kannada.","culturalNote":"Navigation in Bengaluru: Bengaluru''s road network is complex — the city grew rapidly and organically. GPS navigation is very common now (Google Maps used widely — even auto drivers use it!). However, local knowledge is still important. Landmark-based navigation: Bengalurians often give directions using landmarks: ''Rajajinagar metro station hattira'' (near Rajajinagar metro station), ''MG Road metroge hogi'' (go to the MG Road metro). Key navigation landmarks: BBMP (Bruhat Bengaluru Mahanagara Palike — city corporation — very large) offices, police stations, temples, Metro stations (Purple/Green line). Traffic: Bengaluru traffic is notorious — even short distances take long. Suggestion: ask auto drivers for directions — they know every road! Flyovers: ooru inda meele (above — flyover, overpass). One-way: oneway road (one-way street). Signal: traffic signal (traffic light). U-turn: U-turn maadu (take a U-turn)."},"examples":[{"sentence":"Neevu nera hogi, ooru signal alli bala tirigi, naantara eradu mane kaDeyalli namma manege siguttade.","english":"Go straight, turn right at the first signal, then after two houses you will find our house."},{"sentence":"Metro station hattira hogabeku, alli inda naaDakke yele tirigi, naantara 200 metre nera hoguttiri.","english":"You need to go near the metro station, from there turn left on foot, then go straight for 200 metres."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can give detailed directions using landmarks and streets in Kannada."}}',
'{"items":[{"word":"nera","translation":"straight (direction)","transliteration":"nera","pronunciation":"NE-ra","example":"nera hogi"},{"word":"bala","translation":"right (direction)","transliteration":"bala","pronunciation":"BA-la","example":"bala tirigi"},{"word":"yele","translation":"left (direction)","transliteration":"yele","pronunciation":"YE-le","example":"yele tirigi"},{"word":"tirigi","translation":"turn (imperative — turn here)","transliteration":"tirigi","pronunciation":"ti-RI-gi","example":"signal alli tirigi"},{"word":"hattira","translation":"near/close to","transliteration":"hattira","pronunciation":"HAT-ti-ra","example":"metro hattira"},{"word":"daaTi","translation":"cross/pass (go past)","transliteration":"daaTi","pronunciation":"DAA-Ti","example":"signal daaTi hogi"}]}',
'{"title":"Nera hogi, bala tirigi — detailed direction giving in Kannada","pattern":"Nera hogi = go straight. Bala tirigi = turn right. Yele tirigi = turn left. Signal alli bala tirigi = turn right at the signal. X hattira hogabeku = you need to go near X. X daaTi hogi = go past X. X inda Y = from X to Y. Siguttade = you will find/reach it (3rd person neuter — siguttade = it will be found/gotten).","explanation":"Direction vocabulary in Kannada: nera (straight ahead), bala (right), yele (left), meele (above/up), keeLage (below/down). Turn: tirigi (turn — imperative), tirigiri (formal turn). At: X alli tirigi (turn at X). Past: X daaTi hogi (go past X — daaTi = having crossed). Until: X varege hogi (go until X — varege = until). You will find: X siguttade (you will find X — siguttade = will be found/obtained, 3rd neuter). Distance: 200 metre (200 metres), 2 KM (2 kilometres). Landmark phrases: X hattira (near X — hattira = near/close to). Between: X haagu Y ra madhye (between X and Y — madhye = between).","examples":[{"sentence":"Neevu MG Road metro inda yele tirigi, 500 metre nera hogi, ooru junction alli bala tirigi — police station siguttade.","english":"From MG Road metro, turn left, go 500 metres straight, turn right at the first junction — you will find the police station."},{"sentence":"Ee road nera hoguttire naantara ooru flyover siguttade, alli inda keeLage iri.","english":"If you go straight on this road, after some time you will see a flyover, from there stay below/under it."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"bala means?","options":["right (direction)","left","straight","back"],"correctAnswer":"right (direction)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Go straight, turn right at the first signal, then after two houses you will find our house.","options":["Neevu nera hogi, ooru signal alli bala tirigi, naantara eradu mane kaDeyalli namma manege siguttade.","Neevu nera hogi, ooru signal alli yele tirigi, naantara eradu mane kaDeyalli namma manege siguttade.","Neevu nera hogi, ooru signal alli bala tirigi, naantara mooru mane kaDeyalli namma manege siguttade.","Avaru nera hogi, ooru signal alli bala tirigi, naantara eradu mane kaDeyalli namma manege siguttade."],"correctAnswer":"Neevu nera hogi, ooru signal alli bala tirigi, naantara eradu mane kaDeyalli namma manege siguttade."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Metro station ___ hogabeku, alli inda naaDakke yele tirigi.","options":["hattira","inda","alli","varege"],"correctAnswer":"hattira"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: From MG Road metro, turn left, go 500 metres straight.","wordBankItems":["MG","Road","metro","inda","yele","tirigi",",","500","metre","nera","hogi","."],"correctAnswer":"MG Road metro inda yele tirigi , 500 metre nera hogi ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"daaTi means?","options":["cross/pass (go past)","turn","go near","stop at"],"correctAnswer":"cross/pass (go past)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000045',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about daily household chores in Kannada","Use naanu X maaduttini for habitual chores","Discuss division of household responsibilities"],"explanation":{"intro":"Daily chores and household tasks covers vocabulary for all common home tasks — cleaning, cooking, laundry, shopping, and other domestic activities in Kannada.","culturalNote":"Household responsibilities in Karnataka: household chores (mane gudi maaduvudu — housework) are traditionally divided by gender in many Karnataka families — women historically handle cooking and cleaning while men do outdoor tasks. This is changing rapidly in urban Bengaluru. Urban families: many use domestic helpers (mane kaela maaduvavaru) for cleaning and cooking. Appliances: washing machine (washing machine), vacuum cleaner (rare in Indian homes — sweepu/broom used), pressure cooker (a staple), mixie (mixer grinder — indispensable for Karnataka cooking). Water: most Bengaluru homes use Kaveri water (supplied by BWSSB) — scarcity is common, especially in apartments. Water tanker (water tanker) called when municipal supply is insufficient. Gas (LPG): cooking gas — cylinder needs to be booked/ordered (cylinder book maadu). Solar panels: increasingly common on rooftops in Karnataka (sunny climate). Terrace gardening (terrace garden maadu) is trendy in Bengaluru."},"examples":[{"sentence":"Pratidinaa beLigge naanu mane gudi maaduttini, nantara oota maaduttini.","english":"Every morning I clean the house, then I cook food."},{"sentence":"Ee vaara nanna turn alli kapaDa thoLeyabeku, munde vaara nimma turn.","english":"This week it is my turn to wash clothes, next week is your turn."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about daily household chores and domestic responsibilities in Kannada."}}',
'{"items":[{"word":"gudi maadu","translation":"clean/do housework","transliteration":"gudi maadu","pronunciation":"GU-di MAA-du","example":"mane gudi maaduttini"},{"word":"kapaDa thoLe","translation":"wash clothes","transliteration":"kapaDa thoLe","pronunciation":"ka-PA-Da THO-Le","example":"kapaDa thoLeyabeku"},{"word":"oota maadu","translation":"cook food (prepare a meal)","transliteration":"oota maadu","pronunciation":"OO-ta MAA-du","example":"oota maaduttini"},{"word":"angaDi","translation":"grocery/provision shop","transliteration":"angaDi","pronunciation":"an-GA-Di","example":"angaDige hogo"},{"word":"turn","translation":"turn (one''s turn to do a task)","transliteration":"turn","pronunciation":"tarn","example":"nanna turn"},{"word":"barisu","translation":"sweep (to sweep with a broom)","transliteration":"barisu","pronunciation":"ba-RI-su","example":"mane barisi"}]}',
'{"title":"Mane gudi maadu — household chores vocabulary in Kannada","pattern":"X maaduttini = I do X (habitual chore). Mane gudi maaduttini = I clean the house. Kapada thoLeyabeku = clothes must be washed. Turn: ee vaara nanna turn (this week is my turn). Task list: prathama X, nantara Y (first X, then Y). Sharing: naanu X maaduttini, neevu Y maadiri (I will do X, you do Y — maadiri = informal you-do).","explanation":"Household chores vocabulary in Kannada: gudi maadu (clean), barisu (sweep), oota maadu (cook), kapaDa thoLe (wash clothes — thoLeyabeku = need to wash), barTana (dishes — barTana thoLe = wash dishes). Appliance terms: pressure cooker alli X beDisu (cook X in a pressure cooker), mixie alli arayu (grind in a mixie), washing machine alli haaku (put in the washing machine). Shopping: angaDige hogi tarkari taa (go to the shop and bring vegetables — taa = bring). Helper: mane kaela maaduvavaru (the household helper). Responsibility: ee kaela nanna jaavaabdaari (this is my responsibility — jaavaabdaari = responsibility). Division: namma mane alli kaela hanchuttevi (we divide the work at our house — hanchuttevi = we divide).","examples":[{"sentence":"Naanu oota maaduttini, neevu barTana thoLe maadiri — koodi maadona.","english":"I will cook, you wash the dishes — let''s do it together."},{"sentence":"Shani vaara naanu mane gudi maaduttini haagu angaDige hoguttini.","english":"On Saturday I clean the house and also go to the grocery shop."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"gudi maadu means?","options":["clean/do housework","cook food","wash clothes","sweep"],"correctAnswer":"clean/do housework"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Every morning I clean the house, then I cook food.","options":["Pratidinaa beLigge naanu mane gudi maaduttini, nantara oota maaduttini.","Pratidinaa beLigge naanu oota maaduttini, nantara mane gudi maaduttini.","Pratidinaa raatri naanu mane gudi maaduttini, nantara oota maaduttini.","Pratidinaa beLigge avalu mane gudi maaduttaaLe, nantara oota maaduttaaLe."],"correctAnswer":"Pratidinaa beLigge naanu mane gudi maaduttini, nantara oota maaduttini."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ee vaara nanna ___ alli kapaDa thoLeyabeku, munde vaara nimma turn.","options":["turn","gudi","angaDi","barTana"],"correctAnswer":"turn"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I will cook, you wash the dishes — let''s do it together.","wordBankItems":["Naanu","oota","maaduttini",",","neevu","barTana","thoLe","maadiri","—","koodi","maadona","."],"correctAnswer":"Naanu oota maaduttini , neevu barTana thoLe maadiri — koodi maadona ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"angaDi means?","options":["grocery/provision shop","market","supermarket","shop"],"correctAnswer":"grocery/provision shop"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000046',1,'APPROVED','PUBLISHED',
'{"objectives":["Compare things and express preferences in Kannada","Use X, Y ginta channa for comparing","Say which you prefer using naakke X hecchaagi ishtavagutte"],"explanation":{"intro":"Comparing things and preferences covers how to make comparisons, express which option you prefer, and ask others for their preference in Kannada.","culturalNote":"Preferences and comparisons in Karnataka: Kannadigas often compare between regions (North vs South Karnataka food, Bengaluru vs Mysuru lifestyle), between old and new (traditional vs modern), and between local and global. Consumer choices: Kannadigas are known for being practical and value-conscious buyers. The famous ''koDe hana'' (invest-the-money) mindset — Kannadigas think carefully before buying. Mobile phones: comparison between brands (Samsung vs iPhone vs OnePlus) is a common topic. Cars: Maruti Suzuki (made in Manesar but associated with Karnataka because of Bengaluru corporate HQ) vs Tata vs Hyundai. House preference: apartment vs independent house is a huge debate in Bengaluru. Education comparison: English medium vs Kannada medium school debate. Cultural comparison: traditional vs modern Dasara celebration."},"examples":[{"sentence":"Naakke Mysuru, Bengaluru ginta hecchaagi ishtavagutte — peaceful aguttade.","english":"I prefer Mysuru over Bengaluru — it is more peaceful."},{"sentence":"Filter kaapi, tea ginta channa aguttade naakke — tea kaara aagutte.","english":"Filter coffee is better than tea for me — tea tastes bitter."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can compare things and express preferences in Kannada."}}',
'{"items":[{"word":"ginta","translation":"than (comparison marker)","transliteration":"ginta","pronunciation":"GIN-ta","example":"X ginta Y channa"},{"word":"hecchaagi","translation":"more / to a greater degree","transliteration":"hecchaagi","pronunciation":"HECH-chaa-gi","example":"hecchaagi ishtavagutte"},{"word":"kammagi","translation":"less / to a lesser degree","transliteration":"kammagi","pronunciation":"KAM-ma-gi","example":"kammagi kaara"},{"word":"sari samaana","translation":"equally good / the same","transliteration":"sari samaana","pronunciation":"SA-ri sa-MAA-na","example":"sari samaana channa"},{"word":"best","translation":"best (superlative — English word used)","transliteration":"best","pronunciation":"best","example":"naakke best"},{"word":"prefer","translation":"prefer (prefer maadu — use English-Kannada mix)","transliteration":"prefer","pronunciation":"pre-FAR","example":"naanu X prefer maaduttini"}]}',
'{"title":"X, Y ginta channa — X is better than Y (comparison in Kannada)","pattern":"X, Y ginta channa = X is better than Y (ginta = than, comparative marker). X, Y ginta hecchaagi ishtavagutte = I like X more than Y. Superlative: X ella tharagaLalli hecchaagi channa = X is the best of all. Equality: X haagu Y sari samaana channa = X and Y are equally good. Preference question: nimage X ishtava aa Y ishtava? (do you prefer X or Y?).","explanation":"Comparison in Kannada: ginta (than — the key comparative marker). Examples: Kannada, English ginta kaththarige aagutte (Kannada is harder than English — kaththarige aagutte = is difficult to learn). Hecchaagi (more), kammagi (less). Superlative: ella X alli (among all X), hecchaagi channa (the best — most beautiful). Best: best (English word commonly used). Worst: tarahedu aguttide / saraiyalla (it is not good at all). Asking preference: nimage X ishta aa Y ishta? (formal). Expressing preference: naakke X hecchaagi ishtavagutte (I prefer X more). Equal: eraDoo sari samaana (both are equally good — eraDoo = both).","examples":[{"sentence":"Naakke Carnatic sangeetha, film sangeetha ginta hecchaagi ishtavagutte.","english":"I prefer Carnatic music over film music."},{"sentence":"Oota vishayavaagiyu home food, restaurant food ginta hecchaagi channa naakke.","english":"Even in terms of food, home food is better than restaurant food for me."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"ginta means?","options":["than (comparison marker)","more","less","or"],"correctAnswer":"than (comparison marker)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I prefer Mysuru over Bengaluru — it is more peaceful.","options":["Naakke Mysuru, Bengaluru ginta hecchaagi ishtavagutte — peaceful aguttade.","Naakke Bengaluru, Mysuru ginta hecchaagi ishtavagutte — peaceful aguttade.","Naakke Mysuru, Bengaluru ginta kammagi ishtavagutte — peaceful aguttade.","Nimage Mysuru, Bengaluru ginta hecchaagi ishtavagutte — peaceful aguttade."],"correctAnswer":"Naakke Mysuru, Bengaluru ginta hecchaagi ishtavagutte — peaceful aguttade."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Filter kaapi, tea ___ channa aguttade naakke — tea kaara aagutte.","options":["ginta","hecchaagi","kammagi","gunta"],"correctAnswer":"ginta"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I prefer Carnatic music over film music.","wordBankItems":["Naakke","Carnatic","sangeetha",",","film","sangeetha","ginta","hecchaagi","ishtavagutte","."],"correctAnswer":"Naakke Carnatic sangeetha , film sangeetha ginta hecchaagi ishtavagutte ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"hecchaagi means?","options":["more / to a greater degree","less","better","best"],"correctAnswer":"more / to a greater degree"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

